-- Synthetic only. Explicit test-owner grants, not clinical/production templates.
reset role;
update public.hospital_memberships set active=true,valid_until=null,authorization_version=authorization_version+1 where user_id in ('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000002');
insert into public.role_capabilities select r.id,c.code from public.hospital_roles r cross join public.capabilities c where r.code<>'display' and c.code in ('queue.read','queue.coordinate','patient.call','service.accept','treatment.record','work.create','work.assign','work.complete','reassessment.request','escalation.acknowledge','exception.review','coordination.configure') on conflict do nothing;
set role authenticated;
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select set_config('coord.service',public.necms_coordination_configuration('91000000-0000-0000-0000-000000000001','{"kind":"service","code":"TEST","name":"Synthetic assessment coordination"}')->>'id',false);
select set_config('coord.reason',public.necms_coordination_configuration('91000000-0000-0000-0000-000000000002','{"kind":"reason","code":"TEAM","name":"Synthetic team unavailable"}')->>'id',false);
select set_config('coord.team',public.necms_coordination_configuration('91000000-0000-0000-0000-000000000003','{"kind":"team","name":"Synthetic A team"}')->>'id',false);
select public.necms_coordination_configuration('91000000-0000-0000-0000-000000000004',jsonb_build_object('kind','team_member','team_id',current_setting('coord.team'),'user_id','60000000-0000-0000-0000-000000000001'));
select public.necms_coordination_configuration('91000000-0000-0000-0000-000000000005','{"kind":"inactive_policy","version":"synthetic-1","document_reference":"Synthetic governance pending; no rules"}');
-- Existing reviewed 3A encounter is higher urgency; create/review a lower one honestly.
select set_config('coord.high',current_setting('clinical.visit'),false);
select set_config('coord.low',public.necms_record_arrival('{"request_id":"91000000-0000-0000-0000-000000000006","department_id":"a3000000-0000-0000-0000-000000000001","source":"walk-in"}')->>'encounter_id',false);
select set_config('coord.low_assessment',public.necms_record_assessment(current_setting('coord.low')::uuid,1,'{"kind":"initial","request_id":"91000000-0000-0000-0000-000000000007","complaint":"Synthetic lower provisional urgency","manual_priority":4}')::text,false);
select pg_temp.act('60000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001');
select public.necms_review_assessment(current_setting('coord.low_assessment')::uuid,2,'accepted','Synthetic provisional review');
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select set_config('coord.high_work',public.necms_create_work(jsonb_build_object('encounter_id',current_setting('coord.high'),'service_id',current_setting('coord.service'),'kind','initial_review','eligible',true,'title','Synthetic higher waiting'), '92000000-0000-0000-0000-000000000001')->>'id',false);
select set_config('coord.low_input',jsonb_build_object('encounter_id',current_setting('coord.low'),'service_id',current_setting('coord.service'),'kind','treatment','eligible',true,'title','Synthetic treatment coordination')::text,false);
select set_config('coord.low_work',public.necms_create_work(current_setting('coord.low_input')::jsonb,'92000000-0000-0000-0000-000000000002')->>'id',false);
select pg_temp.assert_true(public.necms_create_work(current_setting('coord.low_input')::jsonb,'92000000-0000-0000-0000-000000000002')->>'id'=current_setting('coord.low_work'),'idempotent concurrent-work creation');
select pg_temp.expect_error(format('select public.necms_create_work(%L::jsonb,''92000000-0000-0000-0000-000000000002'')',current_setting('coord.low_input')::jsonb||'{"title":"changed retry"}'),'23514');
select set_config('coord.start',public.necms_work_event(current_setting('coord.low_work')::uuid,1,'start','93000000-0000-0000-0000-000000000001','{}')::text,false);
select pg_temp.assert_true(public.necms_work_event(current_setting('coord.low_work')::uuid,1,'start','93000000-0000-0000-0000-000000000001','{}')=current_setting('coord.start')::jsonb,'event retry survives changed work version');
select pg_temp.assert_true((select state='underway' and version=2 from public.coordination_work_items where id=current_setting('coord.low_work')::uuid),'explicit start without call or acceptance');
select pg_temp.assert_true((select state='waiting' from public.coordination_work_items where id=current_setting('coord.high_work')::uuid),'other work unchanged');
select pg_temp.assert_true((select sequence_status='provisional_sequence_review' and jsonb_array_length(queue_snapshot)=1 and queue_snapshot->0->>'work_item_id'=current_setting('coord.high_work') from public.coordination_events where id=(current_setting('coord.start')::jsonb->>'id')::uuid),'higher same-service queue snapshot');
select set_config('coord.exception',(select id::text from public.operational_exceptions where event_id=(current_setting('coord.start')::jsonb->>'id')::uuid),false);
select pg_temp.assert_true((select count(*)=1 from jsonb_array_elements(public.necms_coordination_board()->'exceptions') e where e->>'review_state'='unexplained'),'missing reason does not block care; provisional unexplained record');
select public.necms_review_sequence(current_setting('coord.exception')::uuid,current_setting('coord.reason')::uuid,'Synthetic operational circumstance; no negligence judgement','94000000-0000-0000-0000-000000000001');
select pg_temp.assert_true((select count(*)=1 from jsonb_array_elements(public.necms_coordination_board()->'exceptions') e where e->>'review_state'='acknowledged'),'acknowledgement distinct from unexplained event');
select public.necms_work_event(current_setting('coord.high_work')::uuid,1,'call','93000000-0000-0000-0000-000000000002','{}');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,1,''accept'',''93000000-0000-0000-0000-000000000003'',''{}'')',current_setting('coord.high_work')),'40001');
select public.necms_work_event(current_setting('coord.high_work')::uuid,2,'call_cancel','93000000-0000-0000-0000-000000000004','{"reason":"Synthetic patient unavailable"}');
select public.necms_work_event(current_setting('coord.high_work')::uuid,3,'accept','93000000-0000-0000-0000-000000000005','{}');
select pg_temp.assert_true((select state='accepted' and acknowledged_at is not null and assignee_id=auth.uid() from public.coordination_work_items where id=current_setting('coord.high_work')::uuid),'verified person acceptance');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,4,''call'',''93000000-0000-0000-0000-000000000006'',''{}'')',current_setting('coord.high_work')),'23514');
select public.necms_work_event(current_setting('coord.high_work')::uuid,4,'reassign','93000000-0000-0000-0000-000000000007','{"assignee_id":"60000000-0000-0000-0000-000000000002","reason":"Synthetic handover"}');
select pg_temp.assert_true((select state='waiting' and acknowledged_at is null from public.coordination_work_items where id=current_setting('coord.high_work')::uuid),'new owner is not silently accepted');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,5,''accept'',''93000000-0000-0000-0000-000000000008'',''{}'')',current_setting('coord.high_work')),'42501');
-- Independent services can coexist without overwriting encounter workflow hints.
select set_config('coord.legacy_hint',(select next_action from public.visits where id=current_setting('coord.low')::uuid),false);
select set_config('coord.lab_service',public.necms_coordination_configuration('91000000-0000-0000-0000-000000000020','{"kind":"service","code":"LAB","name":"Synthetic lab coordination"}')->>'id',false);
select set_config('coord.lab_work',public.necms_create_work(jsonb_build_object('encounter_id',current_setting('coord.low'),'service_id',current_setting('coord.lab_service'),'kind','laboratory','team_id',current_setting('coord.team'),'title','Synthetic concurrent lab work'),'92000000-0000-0000-0000-000000000020')->>'id',false);
select pg_temp.assert_true((select count(*)=2 from public.coordination_work_items where encounter_id=current_setting('coord.low')::uuid),'two concurrent services for one encounter');
select pg_temp.assert_true((select next_action=current_setting('coord.legacy_hint') from public.visits where id=current_setting('coord.low')::uuid),'structured work preserves legacy next action');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,1,''defer'',''93000000-0000-0000-0000-000000000020'',''{}'')',current_setting('coord.lab_work')),'23514');
select public.necms_work_event(current_setting('coord.lab_work')::uuid,1,'readiness','93000000-0000-0000-0000-000000000021','{"eligible":true}');
select public.necms_work_event(current_setting('coord.lab_work')::uuid,2,'defer','93000000-0000-0000-0000-000000000022','{"reason":"Synthetic team temporarily unavailable"}');
select pg_temp.assert_true((select state='deferred' and eligible and acknowledged_at is null from public.coordination_work_items where id=current_setting('coord.lab_work')::uuid),'readiness and deferral remain independent of acceptance');
select public.necms_work_event(current_setting('coord.lab_work')::uuid,3,'resume','93000000-0000-0000-0000-000000000023','{}');
select public.necms_work_event(current_setting('coord.lab_work')::uuid,4,'accept','93000000-0000-0000-0000-000000000024','{}');
select pg_temp.assert_true((select state='accepted' and team_id=current_setting('coord.team')::uuid and acknowledged_at is not null from public.coordination_work_items where id=current_setting('coord.lab_work')::uuid),'verified roster member accepts team work');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,5,''start'',''93000000-0000-0000-0000-000000000025'',''{"occurred_at":"2099-01-01T00:00:00Z","late_entry_reason":"Synthetic invalid future"}'')',current_setting('coord.lab_work')),'23514');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,5,''start'',''93000000-0000-0000-0000-000000000026'',''{"occurred_at":"2026-01-01T00:00:00Z"}'')',current_setting('coord.lab_work')),'23514');
select public.necms_work_event(current_setting('coord.lab_work')::uuid,5,'start','93000000-0000-0000-0000-000000000027','{}');
select pg_temp.assert_true((select jsonb_array_length(queue_snapshot)=0 from public.coordination_events where work_item_id=current_setting('coord.lab_work')::uuid and event='start'),'another service is excluded from sequencing evidence');
select public.necms_work_event(current_setting('coord.lab_work')::uuid,6,'cancel','93000000-0000-0000-0000-000000000028','{"reason":"Synthetic request cancelled by staff"}');
select pg_temp.assert_true((select state='cancelled' from public.coordination_work_items where id=current_setting('coord.lab_work')::uuid),'explicit cancellation preserves record');
-- Unknown urgency and honest late documentation never block an explicit start.
select set_config('coord.unknown_work',public.necms_create_work(jsonb_build_object('encounter_id',(current_setting('clinical.second')::jsonb->>'encounter_id'),'service_id',current_setting('coord.service'),'kind','urgent_review','title','Synthetic urgent request'),'92000000-0000-0000-0000-000000000003')->>'id',false);
select pg_temp.assert_true((select assignee_id=auth.uid() and acknowledged_at is null from public.coordination_work_items where id=current_setting('coord.unknown_work')::uuid),'review request has explicit owner and no false acknowledgement');
select public.necms_work_event(current_setting('coord.unknown_work')::uuid,1,'start','93000000-0000-0000-0000-000000000009','{"occurred_at":"2026-01-01T00:00:00Z","late_entry_reason":"Synthetic earlier care recorded later"}');
select pg_temp.assert_true((select sequence_status='unknown_or_unreviewed_urgency' and occurred_at<recorded_at and details->>'snapshot_basis'='recording_time' from public.coordination_events where work_item_id=current_setting('coord.unknown_work')::uuid and event='start'),'untriaged treatment; honest recording-time snapshot');
select pg_temp.assert_true((select priority is null and triage_state='not_yet_triaged' from public.visits where id=(current_setting('clinical.second')::jsonb->>'encounter_id')::uuid),'work events do not fabricate triage');
select public.necms_work_event(current_setting('coord.unknown_work')::uuid,2,'acknowledge','93000000-0000-0000-0000-000000000010','{}');
select pg_temp.assert_true((select acknowledged_at is not null and state='underway' from public.coordination_work_items where id=current_setting('coord.unknown_work')::uuid),'acknowledgement does not pretend care completed');
select public.necms_work_event(current_setting('coord.unknown_work')::uuid,3,'complete','93000000-0000-0000-0000-000000000011','{}');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,4,''start'',''93000000-0000-0000-0000-000000000012'',''{}'')',current_setting('coord.unknown_work')),'23514');
select pg_temp.assert_true((select count(*)>=3 from public.coordination_work_items where hospital_id='a0000000-0000-0000-0000-000000000001'),'multiple work items without legacy overwrite');
select pg_temp.assert_true(jsonb_array_length(public.necms_coordination_history(current_setting('coord.high')::uuid))>=4,'operational timeline includes immutable transitions');
select pg_temp.act('60000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000001');
select pg_temp.assert_true((select count(*)=0 from public.coordination_work_items where id=current_setting('coord.high_work')::uuid),'direct RLS B cannot read A work');
select pg_temp.assert_true((select count(*)=0 from public.coordination_events where work_item_id=current_setting('coord.high_work')::uuid),'direct RLS B cannot read A event evidence');
select pg_temp.assert_true((select count(*)=0 from public.operational_exceptions where id=current_setting('coord.exception')::uuid),'direct RLS B cannot read A sequencing review');
select pg_temp.assert_true((select count(*)=0 from public.exception_annotations where exception_id=current_setting('coord.exception')::uuid),'direct RLS B cannot read A annotations');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,5,''accept'',''93000000-0000-0000-0000-000000000013'',''{}'')',current_setting('coord.high_work')),'42501');
select pg_temp.expect_error(format('select public.necms_coordination_history(%L::uuid)',current_setting('coord.high')),'42501');
select pg_temp.expect_error(format('select public.necms_create_work(%L::jsonb,''92000000-0000-0000-0000-000000000004'')',current_setting('coord.low_input')::jsonb),'42501');
reset role;
-- Composite FKs remain a boundary even for an owner-level data import.
select pg_temp.expect_error(format('insert into public.coordination_work_items(hospital_id,encounter_id,service_id,kind,created_by,title) values(''b0000000-0000-0000-0000-000000000001'',%L::uuid,%L::uuid,''other'',''60000000-0000-0000-0000-000000000002'',''Synthetic forbidden relationship'')',current_setting('coord.low'),current_setting('coord.service')),'23503');
select pg_temp.expect_error(format('update public.coordination_events set reason=''changed'' where work_item_id=%L::uuid',current_setting('coord.high_work')),'42501');
select pg_temp.expect_error('update public.future_escalation_policies set active=true','42501');
select pg_temp.assert_true((select bool_and(not active) from public.future_escalation_policies),'escalation policy cannot become active');
-- Audit failure must roll back work transition and event atomically.
create function pg_temp.reject_coord_audit() returns trigger language plpgsql as $$begin if new.action='coordination_complete' then raise exception 'Synthetic audit failure' using errcode='23514';end if;return new;end$$;
create trigger synthetic_coord_audit before insert on public.audit_events for each row execute function pg_temp.reject_coord_audit();
set role authenticated;
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,2,''complete'',''93000000-0000-0000-0000-000000000014'',''{}'')',current_setting('coord.low_work')),'23514');
select pg_temp.assert_true((select state='underway' and version=2 from public.coordination_work_items where id=current_setting('coord.low_work')::uuid),'audit failure rolls back work');
select pg_temp.assert_true((select count(*)=0 from public.coordination_events where work_item_id=current_setting('coord.low_work')::uuid and event='complete'),'audit failure leaves no partial event');
reset role;drop trigger synthetic_coord_audit on public.audit_events;
delete from public.role_capabilities where role_id='a1000000-0000-0000-0000-000000000001' and capability='queue.read';
set role authenticated;
select pg_temp.expect_error('select public.necms_coordination_board()','42501');
reset role;
insert into public.role_capabilities values('a1000000-0000-0000-0000-000000000001','queue.read');
set role authenticated;
select pg_temp.act('60000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001');
select pg_temp.assert_true(jsonb_array_length(public.necms_coordination_board()->'work_items')>=4,'fresh authorised context restores access after explicit regrant');
select pg_temp.expect_error(format('update public.coordination_work_items set state=''completed'' where id=%L::uuid',current_setting('coord.low_work')),'42501');
reset role;
update public.hospital_memberships set active=false,authorization_version=authorization_version+1 where hospital_id='a0000000-0000-0000-0000-000000000001' and user_id='60000000-0000-0000-0000-000000000001';
set role authenticated;
select pg_temp.expect_error('select public.necms_coordination_board()','42501');
select pg_temp.expect_error(format('select public.necms_work_event(%L::uuid,2,''complete'',''93000000-0000-0000-0000-000000000015'',''{}'')',current_setting('coord.low_work')),'42501');
select pg_temp.expect_error('select public.necms_coord_retry(null,null,''forged'',''{}'')','42501');
reset role;
select pg_temp.assert_true((select count(*)=0 from public.role_capabilities rc join public.hospital_roles r on r.id=rc.role_id where r.code='display' and rc.capability='queue.read'),'display roles not upgraded');
set role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000003',false);
select set_config('request.headers',jsonb_build_object('x-necms-context',public.necms_create_context('a0000000-0000-0000-0000-000000000001','display')->>'id')::text,false);
select pg_temp.expect_error('select public.necms_coordination_board()','42501');
reset role;set role anon;
select pg_temp.expect_error('select public.necms_coordination_board()','42501');
reset role;
